package com.clueteleporthelper;

import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class ClueTeleportHelperInventoryOverlay extends WidgetItemOverlay {

    private final Client client;
    private final ClueTeleportHelperPlugin plugin;
    private final PanelComponent panelComponent = new PanelComponent();
    private Set<Integer> relevantItemIds = new HashSet<>();

    @Inject
    public ClueTeleportHelperInventoryOverlay(Client client, ClueTeleportHelperPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        showOnInventory();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
        if (relevantItemIds.contains(itemId)) {
            Rectangle bounds = widgetItem.getCanvasBounds();

            // Hot pink fill (more transparent)
            graphics.setColor(new Color(255, 105, 180, 80));
            graphics.fill(bounds);

            // Hot pink border (solid, thicker)
            graphics.setColor(new Color(255, 20, 147));
            graphics.setStroke(new BasicStroke(3));
            graphics.draw(bounds);
        }
    }

    public void updateRelevantItems(List<TeleportData> bestTeleports) {
        relevantItemIds.clear();

        if (bestTeleports == null || bestTeleports.isEmpty()) {
            return;
        }

        // Collect ALL item IDs from ALL best teleports
        for (TeleportData teleport : bestTeleports) {
            relevantItemIds.addAll(teleport.getItemIds());
        }

        // Add items that work for multiple teleports
        relevantItemIds.add(ItemID.LAW_RUNE);

        // If any fairy ring is in the list, add dramen/lunar staff
        if (bestTeleports.stream().anyMatch(t -> t.getName().contains("Fairy Ring"))) {
            relevantItemIds.add(ItemID.DRAMEN_STAFF);
            relevantItemIds.add(ItemID.LUNAR_STAFF);
        }
    }
}

package com.clueteleporthelper;

import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;

public class ClueTeleportHelperPanelOverlay extends Overlay {

    private final Client client;
    private final ClueTeleportHelperPlugin plugin;
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    public ClueTeleportHelperPanelOverlay(Client client, ClueTeleportHelperPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        List<TeleportData> bestTeleports = plugin.getBestTeleports();

        if (bestTeleports == null || bestTeleports.isEmpty()) {
            return null;
        }

        WorldPoint clueLocation = plugin.getClueScrollLocation();
        if (clueLocation == null) {
            return null;
        }

        panelComponent.getChildren().clear();
        panelComponent.setPreferredSize(new Dimension(280, 0));

        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Best Teleports")
                .color(new Color(255, 105, 180))
                .build());

        boolean isOverride = plugin.isOverrideActive();
        String overrideNote = plugin.getOverrideNote();

        if (isOverride && overrideNote != null) {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left(overrideNote)
                    .leftColor(new Color(255, 215, 0))
                    .build());
        }

        // Multi-step mode: show best teleport per step
        if (plugin.isMultiStep()) {
            java.util.List<String> stepNotes = plugin.getMultiStepNotes();
            for (int i = 0; i < bestTeleports.size(); i++) {
                TeleportData teleport = bestTeleports.get(i);
                String fullName = teleport.getName();

                String destination = fullName;
                String itemHint = null;
                int parenStart = fullName.lastIndexOf('(');
                if (parenStart > 0) {
                    destination = fullName.substring(0, parenStart).trim();
                    itemHint = fullName.substring(parenStart + 1, fullName.length() - 1);
                }

                String displayText = "Step " + (i + 1) + ": " + destination;

                panelComponent.getChildren().add(LineComponent.builder()
                        .left(displayText)
                        .leftColor(new Color(255, 182, 193))
                        .right(itemHint)
                        .rightColor(new Color(255, 105, 180))
                        .build());
            }
        } else {
            // Normal single-step mode
            for (int i = 0; i < bestTeleports.size(); i++) {
                TeleportData teleport = bestTeleports.get(i);
                String fullName = teleport.getName();

                String destination = fullName;
                String itemHint = null;
                int parenStart = fullName.lastIndexOf('(');
                if (parenStart > 0) {
                    destination = fullName.substring(0, parenStart).trim();
                    itemHint = fullName.substring(parenStart + 1, fullName.length() - 1);
                }

                String displayText = (i + 1) + ". " + destination;

                panelComponent.getChildren().add(LineComponent.builder()
                        .left(displayText)
                        .leftColor(new Color(255, 182, 193))
                        .right(itemHint)
                        .rightColor(new Color(255, 105, 180))
                        .build());

                // Distance in tiles
                if (teleport.getLocation() != null) {
                    WorldPoint groundClue = new WorldPoint(
                            clueLocation.getX(), clueLocation.getY(), 0);
                    int distance = teleport.getLocation().distanceTo(groundClue);
                    panelComponent.getChildren().add(LineComponent.builder()
                            .right(distance + " tiles")
                            .rightColor(new Color(255, 160, 122))
                            .build());
                }
            }
        }

        return panelComponent.render(graphics);
    }

    private Color getDistanceColor(int distance) {
        if (distance <= 20) {
            return new Color(255, 20, 147);
        } else if (distance <= 50) {
            return new Color(255, 105, 180);
        } else {
            return new Color(255, 182, 193);
        }
    }
}

package com.clueteleporthelper;

import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.LocationClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.CrypticClue;
import net.runelite.client.plugins.cluescrolls.clues.HotColdClue;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.Item;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import java.util.*;
import java.util.stream.Collectors;

@PluginDescriptor(
        name = "Clue Teleport Helper",
        description = "Shows the best teleports for your active clue scroll",
        tags = {"clue", "teleport", "helper"}
)
@PluginDependency(ClueScrollPlugin.class)
public class ClueTeleportHelperPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private ClueScrollPlugin clueScrollPlugin;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ClueTeleportHelperPanelOverlay panelOverlay;

    @Inject
    private ClueTeleportHelperInventoryOverlay inventoryOverlay;

    private static final int MAX_TELEPORTS = 5;
    private static final int[] KEY_MEDIUM_IDS = {
            ItemID.KEY_MEDIUM, ItemID.KEY_MEDIUM_2834, ItemID.KEY_MEDIUM_2836,
            ItemID.KEY_MEDIUM_2838, ItemID.KEY_MEDIUM_2840, ItemID.KEY_MEDIUM_3606,
            ItemID.KEY_MEDIUM_3608, ItemID.KEY_MEDIUM_7297, ItemID.KEY_MEDIUM_7299,
            ItemID.KEY_MEDIUM_7302, ItemID.KEY_MEDIUM_19761
    };

    private List<TeleportData> currentBestTeleports = new ArrayList<>();
    private boolean overrideActive = false;
    private String overrideNote = null;
    private boolean multiStep = false;
    private List<String> multiStepNotes = new ArrayList<>();

    @Override
    protected void startUp() {
        overlayManager.add(panelOverlay);
        overlayManager.add(inventoryOverlay);
        updateRelevantTeleports();
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(panelOverlay);
        overlayManager.remove(inventoryOverlay);
        currentBestTeleports.clear();
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        updateRelevantTeleports();
    }

    private void updateRelevantTeleports() {
        currentBestTeleports.clear();
        multiStep = false;
        multiStepNotes.clear();

        ClueScroll clue = clueScrollPlugin.getClue();
        if (clue == null || clue instanceof HotColdClue) {
            inventoryOverlay.updateRelevantItems(currentBestTeleports);
            return;
        }

        // Check for multi-step clues (three-step cryptics)
        WorldPoint[] allLocations = getAllClueLocations(clue);
        if (allLocations != null && allLocations.length > 1) {
            multiStep = true;
            overrideActive = true;
            overrideNote = "Multi-step clue — " + allLocations.length + " steps remaining";
            for (WorldPoint loc : allLocations) {
                WorldPoint ground = new WorldPoint(loc.getX(), loc.getY(), 0);
                // Check overrides first (handles instanced/special areas)
                LocationOverrides.OverrideResult override = LocationOverrides.getOverride(ground);
                TeleportData best;
                if (override != null && !override.teleports.isEmpty()) {
                    best = override.teleports.get(0);
                } else {
                    best = Arrays.stream(TeleportData.values())
                            .filter(tp -> tp.getLocation() != null)
                            .min(Comparator.comparingInt(tp -> tp.getLocation().distanceTo(ground)))
                            .orElse(null);
                }
                if (best != null) {
                    currentBestTeleports.add(best);
                }
            }
            inventoryOverlay.updateRelevantItems(currentBestTeleports);
            return;
        }

        WorldPoint clueLocation = getClueLocation(clue);
        if (clueLocation == null) {
            // No location — check kill tasks and skill challenges by text
            String clueText = getClueText(clue);

            // Kill task check (cryptic clues like "In a while...")
            KillTaskData.KillTask killTask = KillTaskData.getKillTask(clueText);
            if (killTask != null) {
                currentBestTeleports = new ArrayList<>(killTask.teleports);
                overrideActive = true;
                overrideNote = killTask.monsterNote + " — " + killTask.locationNote;
                inventoryOverlay.updateRelevantItems(currentBestTeleports);
                return;
            }

            // Skill challenge check (Sherlock/Charlie tasks)
            SkillChallengeData.SkillChallenge challenge = SkillChallengeData.getChallenge(clueText);
            if (challenge != null) {
                currentBestTeleports = new ArrayList<>(challenge.teleports);
                overrideActive = true;
                overrideNote = challenge.locationNote;
                inventoryOverlay.updateRelevantItems(currentBestTeleports);
                return;
            }

            inventoryOverlay.updateRelevantItems(currentBestTeleports);
            return;
        }

        // Normalize to plane 0 for distance/override checks — upper floors share
        // the same x,y as ground level, and you always teleport to ground first.
        WorldPoint groundLocation = new WorldPoint(
                clueLocation.getX(), clueLocation.getY(), 0);

        // Check kill-for-key clues first (two-phase: kill monster, then search crate)
        KeyClueData.KeyClue keyClue = KeyClueData.getKeyClue(groundLocation);
        if (keyClue != null) {
            boolean hasKey = hasKeyInInventory();
            if (hasKey) {
                currentBestTeleports = new ArrayList<>(keyClue.crateTeleports);
                overrideNote = keyClue.searchNote;
            } else {
                currentBestTeleports = new ArrayList<>(keyClue.killTeleports);
                overrideNote = keyClue.killNote;
            }
            overrideActive = true;
            fillRemainingTeleports(groundLocation);
            inventoryOverlay.updateRelevantItems(currentBestTeleports);
            return;
        }

        // Check manual overrides (islands, rune altars, etc.)
        LocationOverrides.OverrideResult overrideResult = LocationOverrides.getOverride(groundLocation);
        if (overrideResult != null) {
            currentBestTeleports = new ArrayList<>(overrideResult.teleports);
            overrideActive = true;
            overrideNote = overrideResult.note;
            fillRemainingTeleports(groundLocation);
        } else {
            overrideActive = false;
            overrideNote = null;
            currentBestTeleports = Arrays.stream(TeleportData.values())
                    .filter(tp -> tp.getLocation() != null)
                    .sorted(Comparator.comparingInt(tp -> tp.getLocation().distanceTo(groundLocation)))
                    .limit(MAX_TELEPORTS)
                    .collect(Collectors.toList());
        }

        // Update inventory overlay with new items
        inventoryOverlay.updateRelevantItems(currentBestTeleports);
    }

    /**
     * Fill remaining teleport slots (up to MAX_TELEPORTS) with the closest
     * teleports by distance, skipping any already in the list.
     */
    private void fillRemainingTeleports(WorldPoint location) {
        if (currentBestTeleports.size() >= MAX_TELEPORTS) {
            return;
        }
        Set<TeleportData> existing = new HashSet<>(currentBestTeleports);
        List<TeleportData> extras = Arrays.stream(TeleportData.values())
                .filter(tp -> tp.getLocation() != null && !existing.contains(tp))
                .sorted(Comparator.comparingInt(tp -> tp.getLocation().distanceTo(location)))
                .limit(MAX_TELEPORTS - currentBestTeleports.size())
                .collect(Collectors.toList());
        currentBestTeleports.addAll(extras);
    }

    /**
     * Try to extract text from a clue using only public API methods (no reflection).
     */
    private String getClueText(ClueScroll clue) {
        if (clue == null) {
            return null;
        }

        // Use public toString() method - no reflection needed
        String text = clue.toString();

        // Check if toString() gives us useful text (not just object reference like "ClueScroll@abc123")
        if (text != null && !text.matches(".*@[0-9a-f]+$")) {
            return text;
        }

        // If toString() doesn't contain useful text, return null
        // This means we can't identify kill tasks/skill challenges for this clue type
        return null;
    }

    private boolean hasKeyInInventory() {
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) {
            return false;
        }
        for (Item item : inventory.getItems()) {
            for (int keyId : KEY_MEDIUM_IDS) {
                if (item.getId() == keyId) {
                    return true;
                }
            }
        }
        return false;
    }

    private WorldPoint[] getAllClueLocations(ClueScroll clue) {
        if (clue instanceof LocationClueScroll) {
            WorldPoint[] locations = ((LocationClueScroll) clue).getLocations(clueScrollPlugin);
            if (locations != null && locations.length > 1) {
                return locations;
            }
        }
        return null;
    }

    private WorldPoint getClueLocation(ClueScroll clue) {
        if (clue instanceof LocationClueScroll) {
            WorldPoint[] locations = ((LocationClueScroll) clue).getLocations(clueScrollPlugin);
            if (locations != null && locations.length > 0) {
                return locations[0];
            }
        }
        return null;
    }

    public List<TeleportData> getBestTeleports() {
        return currentBestTeleports;
    }

    public boolean isOverrideActive() {
        return overrideActive;
    }

    public String getOverrideNote() {
        return overrideNote;
    }

    public boolean isMultiStep() {
        return multiStep;
    }

    public List<String> getMultiStepNotes() {
        return multiStepNotes;
    }

    public WorldPoint getClueScrollLocation() {
        ClueScroll clue = clueScrollPlugin.getClue();
        if (clue == null) {
            return null;
        }
        return getClueLocation(clue);
    }
}

package com.clueteleporthelper;

import net.runelite.api.coords.WorldPoint;
import java.util.*;

/**
 * Data for medium clue steps that require killing a monster for a key
 * before searching a crate/drawer. The plugin checks inventory for the key
 * and shows different teleport suggestions depending on which phase the
 * player is in.
 */
public class KeyClueData {

    private static final List<KeyClue> KEY_CLUES = new ArrayList<>();

    static {
        // "A graceful man of many colours..."
        // Kill any Hill Giant → Search crate on 2nd floor of Osten's shop, Shayzien
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(1506, 3590, 2),
                "Kill Hill Giant near Shayzien for key",
                "Search crate on 2nd floor of Osten's shop, Shayzien",
                Arrays.asList(TeleportData.SHAYZIEN, TeleportData.LOVAKENGJ),
                Arrays.asList(TeleportData.SHAYZIEN, TeleportData.LOVAKENGJ)
        ));

        // "Search the basket of apples in an orchard..."
        // Kill any Hill Giant → Search basket of apples in Hosidius
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(1718, 3626, 0),
                "Kill any Hill Giant for key (Edgeville Dungeon / Varrock Sewers)",
                "Search basket of apples in Hosidius orchard",
                Arrays.asList(TeleportData.EDGEVILLE, TeleportData.VARROCK),
                Arrays.asList(TeleportData.HOSIDIUS, TeleportData.XERICS_GLADE)
        ));

        // "Go to the village being attacked by trolls..."
        // Kill Penda in The Toad and Chicken → Search drawers in Dunstan's house, Burthorpe
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2921, 3577, 0),
                "Kill Penda in The Toad and Chicken pub, Burthorpe",
                "Search drawers in Dunstan's house, Burthorpe",
                Arrays.asList(TeleportData.BURTHORPE, TeleportData.WARRIORS_GUILD),
                Arrays.asList(TeleportData.BURTHORPE, TeleportData.WARRIORS_GUILD)
        ));

        // "Go to this building to be illuminated..."
        // Kill guard in Rellekka marketplace → Search drawers on 1st floor of Lighthouse
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2512, 3641, 1),
                "Kill a Guard in Rellekka marketplace for key",
                "Search drawers on 1st floor of Lighthouse",
                Arrays.asList(TeleportData.FAIRY_DKS, TeleportData.HOUSE_RELLEKKA),
                Arrays.asList(TeleportData.FAIRY_ALP)
        ));

        // "In a town where everyone has perfect vision..."
        // Kill any chicken → Search drawers in Seers' Village
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2709, 3478, 0),
                "Kill any Chicken for key (farm south of Seers')",
                "Search drawers opposite Elemental Workshop, Seers' Village",
                Arrays.asList(TeleportData.CAMELOT),
                Arrays.asList(TeleportData.CAMELOT)
        ));

        // "In a town where the guards are armed with maces..."
        // Kill guard dog at Handelmort Mansion → Search upstairs of pub N of Ardougne Castle
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2574, 3326, 1),
                "Kill Guard Dog at Handelmort Mansion, Ardougne",
                "Search upstairs of pub north of Ardougne Castle",
                Arrays.asList(TeleportData.ARDOUGNE),
                Arrays.asList(TeleportData.ARDOUGNE)
        ));

        // "In a town where thieves steal from stalls..."
        // Kill any guard in East Ardougne → Search drawers upstairs in Jerico's house
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2611, 3324, 1),
                "Kill any Guard in East Ardougne for key",
                "Search drawers upstairs in Jerico's house, Ardougne",
                Arrays.asList(TeleportData.ARDOUGNE),
                Arrays.asList(TeleportData.ARDOUGNE)
        ));

        // "In a town where wizards are known to gather..."
        // Kill any man nearby → Search upstairs chest in house NW of Yanille bank
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2593, 3108, 1),
                "Kill any Man in Yanille for key",
                "Search chest upstairs NW of Yanille bank",
                Arrays.asList(TeleportData.WATCHTOWER, TeleportData.HOUSE_YANILLE),
                Arrays.asList(TeleportData.WATCHTOWER, TeleportData.HOUSE_YANILLE)
        ));

        // "Search the upstairs drawers of a house in a village where pirates..."
        // Kill any pirate in Brimhaven → Search drawers upstairs in SE house
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(2809, 3165, 1),
                "Kill any Pirate in Brimhaven for key",
                "Search drawers upstairs in SE Brimhaven house",
                Arrays.asList(TeleportData.HOUSE_BRIMHAVEN, TeleportData.KARAMJA),
                Arrays.asList(TeleportData.HOUSE_BRIMHAVEN, TeleportData.KARAMJA)
        ));

        // "Probably filled with wizards socks."
        // Kill any wizard at Wizards' Tower → Search drawers in basement
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(3116, 9562, 0),
                "Kill any Wizard at the tower for key",
                "Search drawers in Wizards' Tower basement",
                Arrays.asList(TeleportData.WIZARDS_TOWER, TeleportData.FAIRY_DIS),
                Arrays.asList(TeleportData.WIZARDS_TOWER, TeleportData.FAIRY_DIS)
        ));

        // "The dead, red dragon watches over this chest..."
        // Kill any barbarian → Search chest in Barbarian Village
        KEY_CLUES.add(new KeyClue(
                new WorldPoint(3353, 3332, 0),
                "Kill any Barbarian for key",
                "Search chest by the red dragon",
                Arrays.asList(TeleportData.VARROCK, TeleportData.EDGEVILLE),
                Arrays.asList(TeleportData.VARROCK, TeleportData.DIGSITE)
        ));
    }

    /**
     * Check if a clue location matches a kill-for-key clue.
     * Compares on plane 0 with a tolerance of 5 tiles.
     */
    public static KeyClue getKeyClue(WorldPoint clueLocation) {
        for (KeyClue kc : KEY_CLUES) {
            WorldPoint crateGround = new WorldPoint(
                    kc.crateLocation.getX(), kc.crateLocation.getY(), 0);
            if (crateGround.distanceTo(clueLocation) <= 5) {
                return kc;
            }
        }
        return null;
    }

    public static class KeyClue {
        public final WorldPoint crateLocation;
        public final String killNote;
        public final String searchNote;
        public final List<TeleportData> killTeleports;
        public final List<TeleportData> crateTeleports;

        KeyClue(WorldPoint crateLocation, String killNote, String searchNote,
                List<TeleportData> killTeleports, List<TeleportData> crateTeleports) {
            this.crateLocation = crateLocation;
            this.killNote = killNote;
            this.searchNote = searchNote;
            this.killTeleports = killTeleports;
            this.crateTeleports = crateTeleports;
        }
    }
}

package com.clueteleporthelper;

import java.util.*;

/**
 * Data for cryptic clue steps that require killing a specific monster.
 * These clues don't expose a location, so we match by clue text and
 * provide teleport suggestions to reach the monster.
 */
public class KillTaskData {

    private static final List<KillTask> KILL_TASKS = new ArrayList<>();

    static {
        // "In a while..." → Kill a crocodile
        KILL_TASKS.add(new KillTask(
                "In a while",
                "Kill a Crocodile",
                "Kharidian Desert, south of Pollnivneach along River Elid",
                Arrays.asList(TeleportData.HOUSE_POLLNIVNEACH, TeleportData.NARDAH)
        ));

        // "Ghostly bones." → Kill an Ankou
        KILL_TASKS.add(new KillTask(
                "Ghostly bones",
                "Kill an Ankou",
                "Stronghold of Security floor 4, or Catacombs of Kourend",
                Arrays.asList(TeleportData.EDGEVILLE, TeleportData.XERICS_HEART)
        ));

        // "A demon's best friend holds the next step" → Kill a Hellhound
        KILL_TASKS.add(new KillTask(
                "demon's best friend",
                "Kill a Hellhound",
                "Taverley Dungeon, Catacombs of Kourend, or Wilderness",
                Arrays.asList(TeleportData.FALADOR, TeleportData.XERICS_HEART)
        ));

        // "You'll get licked." → Kill a Bloodveld
        KILL_TASKS.add(new KillTask(
                "You'll get licked",
                "Kill a Bloodveld",
                "Slayer Tower or Catacombs of Kourend",
                Arrays.asList(TeleportData.SLAYER_TOWER, TeleportData.XERICS_HEART)
        ));

        // "Reflection is the weakness for these eyes of evil." → Kill a Basilisk
        KILL_TASKS.add(new KillTask(
                "Reflection is the weakness",
                "Kill a Basilisk (bring mirror shield!)",
                "Fremennik Slayer Dungeon or Jormungand's Prison",
                Arrays.asList(TeleportData.FREMENNIK_SLAYER_DUNGEON, TeleportData.FAIRY_DKS)
        ));

        // "Let's hope you don't meet a watery death" → Kill a Waterfiend
        KILL_TASKS.add(new KillTask(
                "watery death",
