    /**
     * Check if a clue's text matches a kill task.
     */
    public static KillTask getKillTask(String clueText) {
        if (clueText == null) {
            return null;
        }
        String lower = clueText.toLowerCase();
        for (KillTask kt : KILL_TASKS) {
            if (lower.contains(kt.textMatch.toLowerCase())) {
                return kt;
            }
        }
        return null;
    }

